import{_ as a,o as l,c as r,a as i}from"./chunks/framework.Ld7uezS_.js";const u=JSON.parse('{"title":"3. 设施保养","description":"","frontmatter":{},"headers":[],"relativePath":"skill/03-maintenance.md","filePath":"skill/03-maintenance.md","lastUpdated":1787283537000}'),e={name:"skill/03-maintenance.md"};function o(n,t,d,s,h,p){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_3-设施保养" tabindex="-1">3. 设施保养 <a class="header-anchor" href="#_3-设施保养" aria-label="Permalink to &quot;3. 设施保养&quot;">​</a></h1><h2 id="本章定位" tabindex="-1">本章定位 <a class="header-anchor" href="#本章定位" aria-label="Permalink to &quot;本章定位&quot;">​</a></h2><p>保养的目标是保持消防设施整洁、完整、可用，并及时发现异常。保养不是维修，也不是擅自改变参数、联动逻辑或设计状态。</p><h2 id="一、先分清巡查、保养、检测和维修" tabindex="-1">一、先分清巡查、保养、检测和维修 <a class="header-anchor" href="#一、先分清巡查、保养、检测和维修" aria-label="Permalink to &quot;一、先分清巡查、保养、检测和维修&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工作</th><th>主要目的</th><th>典型证据</th><th>不能替代什么</th></tr></thead><tbody><tr><td>巡查/值班观察</td><td>及时发现明显异常和状态变化</td><td>时间、位置、外观、控制器信息</td><td>不能替代系统功能检测</td></tr><tr><td>保养</td><td>保持清洁、完整、连接可靠和规定状态</td><td>检查项目、清洁/紧固、状态确认</td><td>不能把异常直接修好，也不能替代法定检测</td></tr><tr><td>检测</td><td>按依据验证输入、显示、动作、反馈和判定结果</td><td>仪器、测点、原始读数、方法、结论</td><td>不能替代故障维修和持续值班</td></tr><tr><td>维修</td><td>查找原因、处理故障并恢复功能</td><td>故障依据、维修动作、部件、复测结果</td><td>不能未经授权改变设计或联动逻辑</td></tr></tbody></table><p>例如，清洁探测器属于保养；清洁后仍反复报警，要进入故障诊断；通过仪器和规定方法确认报警响应，才属于检测。四者可以在一次工作中连续发生，但记录和结论不能混写。</p><h2 id="一、保养前先做四项确认" tabindex="-1">一、保养前先做四项确认 <a class="header-anchor" href="#一、保养前先做四项确认" aria-label="Permalink to &quot;一、保养前先做四项确认&quot;">​</a></h2><ol><li>确认设备、区域、任务和授权；</li><li>评估是否影响报警、联动、灭火、排烟和疏散；</li><li>准备合适的清洁工具、防护用品和记录表；</li><li>需要停用、断电或测试时，落实审批、告知、监护和恢复措施。</li></ol><h2 id="二、先学会什么叫-规定状态" tabindex="-1">二、先学会什么叫“规定状态” <a class="header-anchor" href="#二、先学会什么叫-规定状态" aria-label="Permalink to &quot;二、先学会什么叫“规定状态”&quot;">​</a></h2><p>“规定状态”不是所有设备都调成同一个按钮位置，而是当前设备按照设计、设备说明书、单位制度和任务要求应处于的状态。例如，控制器可能要求正常监视，泵组和风机可能要求自动待命，阀门可能要求处于规定开/关位置，维修中的设备可能允许临时隔离但必须有授权、标识和防护。</p><p>判断规定状态要先查四件事：<strong>对象是什么、当前处于什么工作阶段、依据文件要求什么状态、结束后由谁复核</strong>。不能看到设备“能动”就认为状态正确，也不能把测试中的手动状态留到任务结束。</p><h2 id="三、按-外观—连接—状态—功能—记录-检查" tabindex="-1">三、按“外观—连接—状态—功能—记录”检查 <a class="header-anchor" href="#三、按-外观—连接—状态—功能—记录-检查" aria-label="Permalink to &quot;三、按“外观—连接—状态—功能—记录”检查&quot;">​</a></h2><ul><li><strong>外观</strong>：有无破损、锈蚀、污染、遮挡、标识缺失；</li><li><strong>连接</strong>：安装是否牢固，端子、管线、接地和接口有无异常；</li><li><strong>状态</strong>：控制器、指示灯、主备电、阀门、压力和自动状态是否符合要求；</li><li><strong>功能</strong>：按计划和授权进行功能确认，不以外观正常代替功能测试；</li><li><strong>记录</strong>：写明对象、时间、现象、结果、问题、处理和复核人。</li></ul><h2 id="四、典型设施保养" tabindex="-1">四、典型设施保养 <a class="header-anchor" href="#四、典型设施保养" aria-label="Permalink to &quot;四、典型设施保养&quot;">​</a></h2><ul><li>报警控制器：清洁外观，检查显示、声音、记录、供电和柜内环境；</li><li>探测器和手报：检查安装、污染、遮挡、标识和状态，不随意改地址；</li><li>灭火器：检查位置、标识、铅封/保险销、外观、压力指示（如有）和维修状态；</li><li>泵组和水系统：检查控制柜、泵体、压力表、阀门、管道、渗漏和环境；</li><li>风机、风阀、卷帘、应急照明：检查外观、供电、遮挡、安装和反馈条件。</li></ul><h2 id="五、发现问题怎么办" tabindex="-1">五、发现问题怎么办 <a class="header-anchor" href="#五、发现问题怎么办" aria-label="Permalink to &quot;五、发现问题怎么办&quot;">​</a></h2><p>发现异常时先保护现场和系统，记录事实，不把“正常”写在有问题的项目上；根据单位流程报告并安排维修或检测。保养完成后必须确认自动、联动、监视和规定阀门状态恢复。</p><h2 id="六、设备级保养卡" tabindex="-1">六、设备级保养卡 <a class="header-anchor" href="#六、设备级保养卡" aria-label="Permalink to &quot;六、设备级保养卡&quot;">​</a></h2><p>下面的卡片用于学习“保养要检查什么、怎样判断、发现异常后怎么办”。具体周期、抽检比例、允许误差和部件更换条件，必须查现行维护标准、设备说明书、单位制度和任务方案。</p><h3 id="_5-1-火灾自动报警系统" tabindex="-1">5.1 火灾自动报警系统 <a class="header-anchor" href="#_5-1-火灾自动报警系统" aria-label="Permalink to &quot;5.1 火灾自动报警系统&quot;">​</a></h3><p><strong>保养前</strong>：确认控制器、回路和区域，通知控制室及相关岗位，评估清洁、测试可能造成的报警或联动影响；需要断电或拆装时，落实授权、断电、验电、隔离和临时防护。</p><p><strong>检查项目</strong>：</p><ul><li>控制器、联动控制器、图形显示装置外观、显示、按键、打印/记录和柜内环境；</li><li>探测器、手报、声光警报器、模块和隔离器的安装、标识、污染、遮挡、破损和可见连接；</li><li>主电、备用电源、回路和通信状态，以及屏蔽/隔离清单是否与记录一致；</li><li>按方案进行必要的功能确认，核对输入、显示、动作、反馈和恢复。</li></ul><p><strong>异常处理</strong>：不把清洁完成写成“功能正常”；发现误报、故障、屏蔽、记录缺失或反馈不一致时，保留原始现象，报告并转维修/检测流程。</p><p><strong>恢复与记录</strong>：确认设备回到规定监视状态，无新增故障，记录对象、时间、方法、结果、异常、临时措施和复核人。</p><h3 id="_5-2-自动灭火与消防给水系统" tabindex="-1">5.2 自动灭火与消防给水系统 <a class="header-anchor" href="#_5-2-自动灭火与消防给水系统" aria-label="Permalink to &quot;5.2 自动灭火与消防给水系统&quot;">​</a></h3><p><strong>保养前</strong>：确认水源、泵组、阀组、分区和排水条件，评估误启动、放水、停用和积水风险；未经授权不得关闭控制阀、切断泵组电源或改变压力设定。</p><p><strong>检查项目</strong>：</p><ul><li>水池/水箱水位、补水、溢流、渗漏、标识和环境；</li><li>主泵、备用泵、稳压设施、控制柜、供电、压力显示、阀门状态和反馈；</li><li>报警阀组、信号阀、水流指示器、压力开关、警铃、管道、喷头和消火栓组件；</li><li>末端试水或其他功能确认前，核对方案、排水、防误启动和恢复要求。</li></ul><p><strong>异常处理</strong>：阀门状态异常、漏水、压力异常、泵组不启动、信号不反馈或喷头/栓箱组件损坏时，先评估保护影响、报告并设置临时防护，不擅自放水或拆修。</p><p><strong>恢复与记录</strong>：恢复阀门、供电、自动/联动和控制室监视，确认无渗漏和新增故障，记录测量值、仪器、依据和复核结果。</p><h3 id="_5-3-其他消防设施" tabindex="-1">5.3 其他消防设施 <a class="header-anchor" href="#_5-3-其他消防设施" aria-label="Permalink to &quot;5.3 其他消防设施&quot;">​</a></h3><p><strong>防烟排烟</strong>：清洁风机、控制柜、阀口和执行机构，检查固定件、可见端子、障碍物、异常振动和反馈条件；动作区域无人，测试后恢复控制方式。</p><p><strong>防火门、卷帘、防火阀</strong>：检查门体/帘面/阀体、闭合或启闭部件、密封、导轨、限位、释放器、标识和反馈；不得楔住防火门、站在卷帘下方或反复启动卡阻设备。</p><p><strong>应急照明和疏散指示</strong>：检查灯具、方向、遮挡、集中电源/配电箱、故障显示和通信；应急转换测试后恢复主电、充电和常态监视，不用普通灯具替代。</p><p><strong>消防电话、应急广播和消防电梯接口</strong>：检查分区、通话/播报、线路、备用电源和反馈；电梯迫降须与电梯维保单位协同，不操作安全回路和程序。</p><p><strong>灭火器、室内消火栓</strong>：检查类型、位置、标识、组件、外观、保险销/铅封、压力指示和可用状态；使用后、失压、泄漏或达到维修/报废条件的器材交有资质单位处理。</p><h3 id="_5-4-保养结束判定" tabindex="-1">5.4 保养结束判定 <a class="header-anchor" href="#_5-4-保养结束判定" aria-label="Permalink to &quot;5.4 保养结束判定&quot;">​</a></h3><p>保养结束前逐项确认：</p><ol><li>临时隔离、屏蔽、断电、手动状态和警戒措施是否已经解除或已明确移交；</li><li>控制器、泵组、风机、阀门、卷帘、照明和通信设备是否回到规定状态；</li><li>原有异常是否已转入维修/检测，不能把“已报告”写成“已修复”；</li><li>记录是否包含对象、方法、结果、异常、依据、报告和复核信息。</li></ol><h2 id="七、自测" tabindex="-1">七、自测 <a class="header-anchor" href="#七、自测" aria-label="Permalink to &quot;七、自测&quot;">​</a></h2><ol><li>为什么外观正常不代表功能合格？</li><li>清洁探测器前要确认什么？</li><li>保养和维修的边界是什么？</li><li>记录中发现异常时为什么不能填写“正常”？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a>；建筑消防设施维护应查现行 GB 25201、设备说明书和单位制度。现场保养必须在授权和安全措施下进行。</p></blockquote>',43)])])}const g=a(e,[["render",o]]);export{u as __pageData,g as default};
